// tb.v: random-stimulus testbench for Resets, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg rst = 1'b0;
    reg arst_n = 1'b1;
    reg soft_rst_n = 1'b0;
    reg [7:0] din = 8'd0;
    reg sel = 1'b0;
    wire [7:0] oa;
    wire [7:0] ob;
    wire [7:0] oc;
    wire [7:0] od;
    wire [7:0] oe;
    wire [7:0] on;
    wire [3:0] op;
    wire [7:0] oq;
    reg [9:0] stim [0:239];
    integer i;

    Resets dut (
        .clk(clk),
        .rst(rst),
        .arst_n(arst_n),
        .soft_rst_n(soft_rst_n),
        .din(din),
        .sel(sel),
        .oa(oa),
        .ob(ob),
        .oc(oc),
        .od(od),
        .oe(oe),
        .on(on),
        .op(op),
        .oq(oq)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            rst = 1'b1;
            arst_n = 1'b0;
            #1;
            cycle_clk;
            cycle_clk;
            rst = 1'b0;
            arst_n = 1'b1;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {soft_rst_n, din, sel} = stim[i];
            #1;
            $display("D %0d %h %h %h %h %h %h %h %h", i, oa, ob, oc, od, oe, on, op, oq);
            cycle_clk;
        end
        $finish;
    end
endmodule
